<script lang="ts">
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();
 import {ArrowLeft,Layers,Wand2,Pencil,ChevronRight} from 'lucide-svelte';
 import {interiorMembers,terrainMaskLabel,type PixelArtPack,type MapBrush,type TileKind} from '@isometrico/world';
 import {workshopTiles} from '$lib/workshop/resources';
 import SpriteThumbnail from './SpriteThumbnail.svelte';
 let {graphics,brush,selectedFamily=null,onfamilychange,onchoose,onedit}:{graphics:PixelArtPack;brush:MapBrush|null;selectedFamily?:string|null;onfamilychange:(id:string|null)=>void;onchoose:(brush:MapBrush,label:string)=>void;onedit:(tile:TileKind)=>void}=$props();
 const tiles=$derived(workshopTiles(graphics)),families=$derived(graphics.tileFamilies??{}),family=$derived(selectedFamily?families[selectedFamily]:undefined);
 const grouped=$derived(new Set(Object.values(families).flatMap(f=>Object.keys(f.tiles))));
 const ungrouped=$derived(tiles.filter(t=>!grouped.has(t.id)));
 const borders=$derived(family?tiles.filter(t=>Object.values(family.borders??{}).includes(t.id)):[]);
 const variants=$derived(family?tiles.filter(t=>Object.hasOwn(family.tiles,t.id)&&!borders.some(b=>b.id===t.id)):[]);
 const primary=$derived(family?interiorMembers(family)[0]?.id:undefined);
 let query=$state('');const matches=(text:string)=>text.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase());
 function openFamily(id:string){onfamilychange(id);onchoose(`terrain:${id}`,families[id].name);}
 function borderLabel(id:TileKind){return Object.entries(family?.borders??{}).filter(([,tile])=>tile===id).map(([mask])=>terrainMaskLabel(Number(mask))).join(' / ');}
</script>
<section class="terrain-palette" aria-label={ui.text("Paleta de suelos")}>
 {#if family&&selectedFamily}
  <button type="button" class="back" onclick={()=>onfamilychange(null)}><ArrowLeft size={15}/>{ui.text("Todos los suelos")}</button>
  <div class="family-heading"><Layers size={18}/><strong>{family.name}</strong><small>{Object.keys(family.tiles).length} {ui.text("piezas")}</small></div>
  <button type="button" class="automatic" aria-pressed={brush===`terrain:${selectedFamily}`} onclick={()=>onchoose(`terrain:${selectedFamily}`,family.name)}><Wand2 size={18}/><span>{ui.text("Pintar automáticamente")}<small>{ui.text("Variaciones y bordes")}</small></span></button>
  <h4>{ui.text("Variaciones interiores")}</h4>
  <div class="pieces" aria-label={ui.text("Variaciones interiores")}>{#each variants as tile}<button type="button" aria-pressed={brush===tile.id} title={tile.label} onclick={()=>onchoose(tile.id,tile.label)}><SpriteThumbnail image={tile.image} frame={tile.frame} width={64} height={32}/><span>{tile.label}</span></button>{/each}</div>
  {#if borders.length}<details open={borders.some(t=>t.id===brush)}><summary><ChevronRight size={14}/>{ui.text("Piezas de borde")}<small>{borders.length}</small></summary><div class="pieces borders" aria-label={ui.text("Piezas de borde")}>{#each borders as tile}<button type="button" aria-pressed={brush===tile.id} aria-label={ui.text("Pintar borde {arg0}",{arg0:borderLabel(tile.id)})} title={tile.label} onclick={()=>onchoose(tile.id,tile.label)}><SpriteThumbnail image={tile.image} frame={tile.frame} width={64} height={32}/><span>{borderLabel(tile.id)}</span></button>{/each}</div></details>{/if}
  {#if primary}<button type="button" class="edit" onclick={()=>onedit(primary)}><Pencil size={14}/>{ui.text("Editar familia en el taller")}</button>{/if}
 {:else}
  {#if Object.keys(families).length+ungrouped.length>12}<input class="search" aria-label={ui.text("Buscar suelo")} placeholder={ui.text("Buscar suelo…")} bind:value={query}/>{/if}
  <div class="pieces catalog" aria-label={ui.text("Todos los suelos")}>{#each Object.entries(families).filter(([,f])=>matches(f.name)) as [id,f]}{@const tile=tiles.find(t=>t.id===interiorMembers(f)[0]?.id)}<button type="button" class="family-card" aria-label={ui.text("Abrir familia {arg0}",{arg0:f.name})} aria-pressed={brush===`terrain:${id}`} onclick={()=>openFamily(id)}>{#if tile}<SpriteThumbnail image={tile.image} frame={tile.frame} width={64} height={32}/>{/if}<span>{f.name}</span><small><Layers size={12}/>{Object.keys(f.tiles).length} {ui.text("piezas")}</small></button>{/each}{#each ungrouped.filter(t=>matches(t.label)) as tile}<button type="button" aria-pressed={brush===tile.id} onclick={()=>onchoose(tile.id,tile.label)}><SpriteThumbnail image={tile.image} frame={tile.frame} width={64} height={32}/><span>{tile.label}</span></button>{/each}<button type="button" aria-pressed={brush==='void'} onclick={()=>onchoose('void',ui.text("Vacío"))}><span class="empty" aria-hidden="true"></span><span>{ui.text("Vacío")}</span></button></div>
 {/if}
</section>
<style>
 .terrain-palette{display:grid;gap:12px;min-width:0;color:#3c5135}.pieces{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.pieces button{min-width:0;display:grid;justify-items:center;align-content:center;gap:6px;padding:10px 5px;background:#fffef9;border:1px solid #dce5d6;border-radius:8px;font-size:11px;color:inherit;cursor:pointer}.pieces button span{max-width:100%;overflow-wrap:anywhere;text-align:center}.pieces button small{display:flex;align-items:center;gap:4px;font-size:10px;color:#718269}.pieces .family-card{background:#eff4e8}.pieces button:hover,.edit:hover{background:#e8efde}button[aria-pressed=true]{background:#d8e8c9;border-color:#789557}.back,.edit{display:flex;align-items:center;gap:6px;font-size:11px;color:#607359;background:transparent;border:0;padding:5px 0;cursor:pointer}.edit{padding:9px;border:1px solid #dce5d6;border-radius:7px;justify-content:center}.family-heading{display:flex;align-items:center;gap:7px;min-width:0}.family-heading strong{font-size:14px;overflow-wrap:anywhere;flex:1}.family-heading small{font-size:10px;color:#718269;white-space:nowrap}.automatic{display:flex;align-items:center;gap:9px;padding:11px;text-align:left;border:1px solid #dce5d6;border-radius:8px;background:#f1f5e9;color:inherit;cursor:pointer;font-size:12px}.automatic span{display:grid;gap:4px}.automatic small{font-size:10px;color:#718269}h4{font-size:11px;font-weight:600;margin:2px 0 0}details{border-top:1px solid #dce5d6;padding-top:10px}summary{display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;list-style:none;padding:4px 0}summary::-webkit-details-marker{display:none}summary small{margin-left:auto;color:#718269}details[open] summary :global(svg){transform:rotate(90deg)}.borders{margin-top:8px}.search{box-sizing:border-box;min-width:0;width:100%;border:1px solid #dce5d6;background:#fff;border-radius:7px;padding:9px;color:inherit;font:inherit;font-size:12px}.empty{width:64px;height:32px;border:1px dashed #829d7a;background:#edf2e5;box-sizing:border-box;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}button:focus-visible,summary:focus-visible,input:focus-visible{outline:2px solid #74994e;outline-offset:2px}
</style>
